"""Give the MATLAB domain its own HTML anchor namespace.

Generated by Claude Opus 5.

Problem
-------
``sphinxcontrib.matlab`` mints node IDs exactly the way the Python domain
does: ``module-<modname>`` for ``.. mat:module::`` and ``<fullname>`` for
functions/classes/methods.  If the same dotted name is documented in both
domains inside the *same* source file you get::

    <autodoc>:1: CRITICAL: Duplicate ID: "module-foo".

and, for non-module objects, a silent failure: matlabdomain skips the ID
(``if fullname_out not in self.state.document.ids``), so the MATLAB entry
gets no anchor at all and ``:mat:class:`foo.Bar``` links to the *Python*
``foo.Bar``.

Fix
---
Prefix every mat-domain anchor with ``mat-``.  Four places have to agree:
the directives that emit targets, ``resolve_xref``, ``get_objects``
(search index + objects.inv), and the MATLAB module index.

Usage
-----
Put this file next to ``conf.py`` (or in ``docs/_ext/``) and add::

    import sys, os
    sys.path.insert(0, os.path.abspath("."))        # or ".../_ext"
    extensions = ["sphinxcontrib.matlab", "sphinx.ext.autodoc", "mat_unique_ids"]

Load it *after* ``sphinxcontrib.matlab``.

Written against sphinxcontrib-matlabdomain master (0.22.x).  Verify with::

    python -c "import inspect,sphinxcontrib.matlab as m; print(inspect.getsource(m.MatModule.run))"

If upstream has changed, re-sync ``_run`` / ``_add_target_and_index`` below.
"""

import sphinxcontrib.matlab as matlab
from docutils import nodes
from sphinx import addnodes
from sphinx.locale import _ as _translate
from sphinxcontrib import mat_types

#: Namespace applied to every ID/anchor produced by the ``mat`` domain.
PREFIX = "mat-"

#: Set to False to only fix module anchors (the ones that emit the CRITICAL)
#: and leave function/class/method anchors alone.
PREFIX_OBJECTS = True


# --------------------------------------------------------------------------
# 1. .. mat:module:: foo   ->  id "mat-module-foo" instead of "module-foo"
# --------------------------------------------------------------------------
def _run(self):
    env = self.state.document.settings.env
    modname = self.arguments[0].strip()
    if not env.config.matlab_keep_package_prefix:
        modname_out = mat_types.strip_package_prefix(modname)
    else:
        modname_out = modname

    env.temp_data["mat:module"] = modname
    if "noindex" in self.options:
        return []

    env.domaindata["mat"]["modules"][modname] = (
        env.docname,
        self.options.get("synopsis", ""),
        self.options.get("platform", ""),
        "deprecated" in self.options,
    )
    # duplicate entry in 'objects' so MATLABDomain.find_obj() sees the module
    env.domaindata["mat"]["objects"][modname] = (env.docname, "module")

    node_id = f"{PREFIX}module-{modname}"
    targetnode = nodes.target("", "", ids=[node_id], ismod=True)
    self.state.document.note_explicit_target(targetnode)

    indextext = _translate("%s (module)") % modname_out  # was matlab.translation(...)
    inode = addnodes.index(entries=[("single", indextext, node_id, "", None)])
    return [targetnode, inode]


matlab.MatModule.run = _run


# --------------------------------------------------------------------------
# 2. functions / classes / methods / properties
# --------------------------------------------------------------------------
def _add_target_and_index(self, name_cls, sig, signode):  # noqa: ARG002
    modname = self.options.get("module", self.env.temp_data.get("mat:module")) or ""
    if self.env.config.matlab_short_links and name_cls[0] != modname:
        modname = ".".join(p for p in modname.split(".") if p.startswith("+"))

    fullname = ((modname and f"{modname}.") or "") + name_cls[0]
    fullname = fullname.lstrip(".")
    if not self.env.config.matlab_keep_package_prefix:
        modname_out = mat_types.strip_package_prefix(modname)
        fullname_out = ((modname_out and f"{modname_out}.") or "") + name_cls[0]
        fullname_out = fullname_out.lstrip(".")
    else:
        modname_out, fullname_out = modname, fullname

    node_id = PREFIX + fullname_out
    if node_id not in self.state.document.ids:
        signode["names"].append(node_id)
        signode["ids"].append(node_id)
        signode["first"] = not self.names
        self.state.document.note_explicit_target(signode)

    objects = self.env.domaindata["mat"]["objects"]
    if fullname_out in objects:
        self.state_machine.reporter.warning(
            f"duplicate object description of {fullname_out}, other instance in "
            f"{self.env.doc2path(objects[fullname_out][0])}, "
            "use :noindex: for one of them",
            line=self.lineno,
        )
    objects[fullname_out] = (self.env.docname, self.objtype)

    indextext = self.get_index_text(modname_out, name_cls)
    if indextext:
        self.indexnode["entries"].append(("single", indextext, node_id, "", None))


if PREFIX_OBJECTS:
    # every mat directive class derives from MatObject, so one assignment
    # covers function/class/method/attribute/script/application/...
    matlab.MatObject.add_target_and_index = _add_target_and_index


# --------------------------------------------------------------------------
# 3. cross references -- MATLABDomain.resolve_xref() calls the module-global
#    make_refnode(), so swapping that symbol is enough.
# --------------------------------------------------------------------------
_orig_make_refnode = matlab.make_refnode


def _make_refnode(builder, fromdocname, todocname, targetid, child, title=None):
    if targetid and not targetid.startswith(PREFIX):
        if targetid.startswith("module-") or PREFIX_OBJECTS:
            targetid = PREFIX + targetid
    return _orig_make_refnode(builder, fromdocname, todocname, targetid, child, title)


matlab.make_refnode = _make_refnode


# --------------------------------------------------------------------------
# 4. search index / objects.inv
# --------------------------------------------------------------------------
_orig_get_objects = matlab.MATLABDomain.get_objects


def _get_objects(self):
    for name, dispname, objtype, docname, anchor, prio in _orig_get_objects(self):
        if not anchor.startswith(PREFIX) and (objtype == "module" or PREFIX_OBJECTS):
            anchor = PREFIX + anchor
        yield name, dispname, objtype, docname, anchor, prio


matlab.MATLABDomain.get_objects = _get_objects


# --------------------------------------------------------------------------
# 5. the "MATLAB Module Index" page
# --------------------------------------------------------------------------
_orig_generate = matlab.MATLABModuleIndex.generate


def _generate(self, docnames=None):
    content, collapse = _orig_generate(self, docnames)
    for _letter, entries in content:
        for entry in entries:
            if entry[3] and not entry[3].startswith(PREFIX):
                entry[3] = PREFIX + entry[3]
    return content, collapse


matlab.MATLABModuleIndex.generate = _generate


def setup(app):
    return {"version": "1.0", "parallel_read_safe": False}
